m = load(name='r9st', sources=[d + '/kernel.cu', d + '/bind.cpp'], extra_cuda_cflags=['-O3', '--use_fast_math', '-std=c++17'],
         extra_ldflags=['-lcuda'], build_directory=d, verbose=False)
r = subprocess.run(['cuobjdump', '-res-usage', m.__file__], capture_output=True, text=True)
print([l.strip() for l in r.stdout.splitlines() if 'STACK' in l or 'Function' in l][:8])
dev = 'cuda'
flush = torch.empty(252 * 1024 * 1024 // 4, device=dev)
rows = [(2, 768, 7, 7), (8, 768, 7, 7), (16, 768, 7, 7), (32, 768, 7, 7), (8, 384, 14, 14), (16, 384, 14, 14)]
cols = [(14, 'w1a'), (15, 'w1b'), (16, 'cb'), (17, 'cv'), (1, 'Aend'), (2, 's1'), (18, 'w2i'), (19, 'w2b'), (4, 'G1'), (7, 's2'), (9, 'end')]
