#pragma unroll
      for (int j = 0; j < NQ; j++) v[k][j] = __ldg(src + lane + 32 * j);
    }
  }
  const float4* gb4 = reinterpret_cast<const float4*>(p.gb + qtr * C_);
#pragma unroll
  for (int k = 0; k < MW; k++) {
    const int u = wid + k * nwk;
    if (u < C4) {
      const int row = u >> 2;
      uint2* dst = reinterpret_cast<uint2*>(p.w2h + (size_t)row * C4 + qtr * C_);
