        sg += v[k][j].x * g4.x + v[k][j].y * g4.y + v[k][j].z * g4.z + v[k][j].w * g4.w;
        uint2 o; o.x = h2u(__floats2half2_rn(v[k][j].x, v[k][j].y)); o.y = h2u(__floats2half2_rn(v[k][j].z, v[k][j].w));
