#pragma unroll
      for (int o = 0; o < 7; o++) acc[o] = 0.f;
#pragma unroll
      for (int i = 0; i < 7; i++) {
        const int hh = h + i - 3;
        if (hh >= 0 && hh < H_) {
          float v[13];
#pragma unroll
          for (int jj = 0; jj < 13; jj++) { const int col = w0 - 3 + jj; v[jj] = (col >= 0 && col < W_) ? xp[hh * W_ + col] : 0.f; }
